<script setup lang="ts">import { computed, onMounted, ref } from 'vue'; import { Save, Moon, Sun, Globe2, Database, CheckCircle2 } from 'lucide-vue-next'; import PageHeader from '../components/PageHeader.vue'; import { useResourcesStore } from '../stores/resources'; import { useAppStore } from '../stores/app'; import { api } from '../api/client'; const store = useResourcesStore(); const app = useAppStore(); const timezone = ref(Intl.DateTimeFormat().resolvedOptions().timeZone); const language = ref('zh-CN'); const saving = ref(false); const saved = ref(false); const current = computed(() => store.settings.settings); onMounted(async () => { try { await store.loadSettings(); timezone.value = String(current.value.timezone || timezone.value); language.value = String(current.value.language || 'zh-CN') } catch {} }); async function save() { saving.value = true; try { await api.updateSettings({ ...current.value, timezone: timezone.value, language: language.value }); saved.value = true; app.toast('设置已保存'); setTimeout(() => saved.value = false, 2500) } catch (e) { app.toast(e instanceof Error ? e.message : '保存失败') } finally { saving.value = false } }</script>
<template><section class="page-content settings-page"><PageHeader eyebrow="工作台偏好" title="设置" description="调整时间、主题和本地数据的显示方式。"><button class="button button-primary" :disabled="saving" @click="save"><Save :size="16" />{{ saving ? '保存中…' : '保存设置' }}</button></PageHeader><div class="settings-layout"><section class="panel settings-card"><div class="settings-section"><div class="settings-section-title"><Globe2 :size="18" /><div><h3>地区与时间</h3><p>截止日期会按这个时区显示。</p></div></div><label>时区<select v-model="timezone"><option>{{ timezone }}</option><option>Asia/Shanghai</option><option>Asia/Tokyo</option><option>UTC</option></select></label><label>语言<select v-model="language"><option value="zh-CN">简体中文</option><option value="en-US">English</option></select></label></div><div class="settings-section"><div class="settings-section-title"><component :is="app.theme === 'light' ? Sun : Moon" :size="18" /><div><h3>外观</h3><p>选择适合当前环境的阅读主题。</p></div></div><div class="theme-picker"><button :class="{ active: app.theme === 'light' }" @click="app.setTheme('light')"><Sun :size="17" />浅色</button><button :class="{ active: app.theme === 'dark' }" @click="app.setTheme('dark')"><Moon :size="17" />深色</button></div></div><div class="settings-section"><div class="settings-section-title"><Database :size="18" /><div><h3>数据与隐私</h3><p>数据默认保留在本地服务；前端不读取 provider secret。</p></div></div><div class="privacy-note"><CheckCircle2 :size="16" />本地优先 · 不上传原始消息文本</div></div></section><aside class="panel settings-side"><p class="section-kicker">服务状态</p><h3>{{ app.online ? '运行正常' : '等待连接' }}</h3><p class="muted-copy">{{ app.online ? 'REST API 与实时通知通道已准备好。' : '请确认本地 CampusCue 服务已在 6200 端口运行。' }}</p><div class="system-details"><span>前端版本<strong>M6</strong></span><span>API<strong>/api/v1</strong></span><span>保存状态<strong>{{ saved ? '已保存' : '未修改' }}</strong></span></div></aside></div></section></template>
